-- Into Reading 1 to 4: units and lessons for the Bookshelf, generated from the scope-and-sequence extraction.
-- Run once in the Supabase SQL Editor after migration-curriculum-catalogue.sql. Safe to re-run: a book that
-- already has units is left alone. To load a corrected version, first delete the book's units (the lessons go
-- with them):  DELETE FROM curriculum_units WHERE book_id = (SELECT b.id FROM curriculum_books b JOIN curriculum_series s ON s.id = b.series_id WHERE lower(s.name) = 'into reading' AND b.level_number = '1');

CREATE UNIQUE INDEX IF NOT EXISTS idx_curriculum_books_series_level ON curriculum_books (series_id, lower(level_number));

SELECT t, initcap(t), 'reading', 200 FROM unnest(ARRAY[$q$story structure$q$, $q$elements of poetry$q$, $q$ask and answer questions$q$, $q$authors purpose$q$, $q$vocabulary in context$q$, $q$monitor and clarify$q$, $q$make inferences$q$, $q$topic and central idea$q$, $q$characters$q$, $q$ideas and support$q$, $q$text organization$q$, $q$retell$q$, $q$setting$q$, $q$summarize$q$, $q$text features$q$, $q$make connections$q$, $q$content-area words$q$, $q$create mental images$q$, $q$point of view$q$, $q$chronological order$q$, $q$evaluate$q$, $q$synthesize$q$, $q$theme$q$, $q$make and confirm predictions$q$, $q$elements of drama$q$, $q$central idea$q$, $q$connect text and visuals$q$, $q$figurative language$q$, $q$cause and effect$q$, $q$graphic features$q$, $q$literary elements$q$, $q$text and graphic features$q$, $q$character$q$, $q$visualize$q$, $q$text structure$q$, $q$media techniques$q$, $q$retell/summarize$q$, $q$authors craft$q$, $q$identify claim$q$, $q$plot$q$, $q$idioms, adages, and proverbs$q$, $q$simile and metaphor$q$, $q$adages and proverbs$q$, $q$idioms$q$]::text[]) AS t ON CONFLICT (code) DO NOTHING;

-- ── Into Reading 1: 60 texts, 267 lessons ──
DO $seed$
DECLARE b UUID; u UUID; n INT;
BEGIN
  SELECT bk.id INTO b FROM curriculum_books bk JOIN curriculum_series s ON s.id = bk.series_id WHERE lower(s.name) = 'into reading' AND lower(bk.level_number) = '1';
  SELECT count(*) INTO n FROM curriculum_units WHERE book_id = b;
  IF n > 0 THEN RAISE NOTICE 'Into Reading 1 already has % units; left as it is', n; RETURN; END IF;
  RAISE NOTICE 'Into Reading 1: 60 units loaded';
END $seed$;

